// repeatable fields are arrays of controls, reading the value back in its
// wire form, and binding a server `request-validation` problem's field errors
// onto the controls they name. A field-error path is dot-separated wire names
// relative to the body, array elements as `[n]` -- the one path rule every
// backend realizes.

import { type AbstractControl, FormArray, FormGroup } from '@angular/forms';

import type { FieldError } from './problem';

